<?php declare(strict_types=1);require dirname(__DIR__).'/includes/bootstrap.php';require_vendor();$vendor=vendor_user();if(is_post()){verify_csrf();if(!rate_limit('vendor-redeem',20,60))flash('error','Too many redemption attempts.');else try{$result=redeem_gift_code($vendor,(string)input('code'));flash('success','Redeemed '.$result['gift'].' ('.$result['redemption_id'].').');}catch(RuntimeException $e){flash('error',$e->getMessage());}redirect('/vendor/redeem.php');}$notices=take_flashes();?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Redeem code · Hunter</title><link rel="stylesheet" href="<?=e(app_url('/assets/css/style.css'))?>"></head><body class="login-page"><main class="login-card"><h1>Redeem gift</h1><p><?=e($vendor['shop_name'])?> · Validation is performed on the server.</p><?php foreach($notices as $n):?><div class="alert <?=e($n['type'])?>"><?=e($n['message'])?></div><?php endforeach?><form method="post" data-confirm="Redeem this single-use code now?"><?=csrf_field()?><div class="field"><label>Reward code</label><input name="code" maxlength="64" autocomplete="off" required autofocus></div><button class="btn">Validate & redeem</button><a class="btn secondary" href="<?=e(app_url('/vendor/dashboard.php'))?>">Dashboard</a></form></main><script src="<?=e(app_url('/assets/js/app.js'))?>"></script></body></html>
